// Respuesta para el panel de Marketing: texto limpio, productos reales de la busqueda y sugerencias.
const ag = $('Agente').first().json;
const salida = String(ag.output || '');

// Productos que devolvio buscar_productos en este turno (la observacion puede venir como texto JSON).
const encontrados = new Map();
const juntar = (x, prof = 0) => {
  if (x == null || prof > 6) return;
  if (typeof x === 'string') {
    const t = x.trim();
    if (!t.startsWith('{') && !t.startsWith('[')) return;
    try { x = JSON.parse(t); } catch (e) { return; }
  }
  if (Array.isArray(x)) { x.forEach((v) => juntar(v, prof + 1)); return; }
  if (typeof x !== 'object') return;
  if (x.codigo != null && x.descripcion) {
    const codigo = String(x.codigo).trim();
    if (!encontrados.has(codigo)) {
      const st = x.stock || {};
      const inventario = st.INVENTARIO != null ? Number(st.INVENTARIO)
        : Object.values(st).reduce((s, v) => s + (Number(v) || 0), 0);
      encontrados.set(codigo, {
        codigo, descripcion: String(x.descripcion), precio: x.precio != null ? Number(x.precio) : null,
        unidad: x.unidad || null, inventario: Number.isFinite(inventario) ? inventario : null,
        tiene_imagen: !!x.tiene_imagen, tiene_ficha: !!x.tiene_ficha, atributos: x.atributos || null,
      });
    }
  }
  for (const v of Object.values(x)) juntar(v, prof + 1);
};
for (const paso of ag.intermediateSteps || []) {
  if ((paso.action && paso.action.tool) === 'buscar_productos') juntar(paso.observation);
}

// Codigos en el orden en que Camila los menciono ("(cód. 1234)").
const codigos = [];
for (const m of salida.matchAll(/c[oó]d\.?\s*:?\s*([A-Za-z0-9._-]+)/gi)) {
  const c = m[1].replace(/[.)]+$/, '');
  if (encontrados.has(c) && !codigos.includes(c)) codigos.push(c);
}

// "Sugerencias: a | b | c" (ultima linea) se separa del texto.
let sugerencias = [];
const lineas = salida.split('\n');
const iSug = lineas.findIndex((l) => /^\s*\**sugerencias?\**\s*:/i.test(l));
if (iSug !== -1) {
  sugerencias = lineas[iSug].replace(/^\s*\**sugerencias?\**\s*:\s*/i, '').split('|')
    .map((s) => s.replace(/[*_]/g, '').trim()).filter(Boolean).slice(0, 3);
  lineas.splice(iSug, 1);
}

// El texto sin los renglones de productos (el panel los muestra como tarjetas).
const texto = lineas.filter((l) => !/c[oó]d\.?\s*:?\s*[A-Za-z0-9]/i.test(l)).join('\n')
  .replace(/\*/g, '').replace(/\n{3,}/g, '\n\n').trim();

return [{ json: {
  ok: true,
  texto: texto || salida.replace(/\*/g, '').trim(),
  productos: codigos.slice(0, 6).map((c) => encontrados.get(c)),
  sugerencias,
  salida_original: salida,
  execution_id: $execution.id,
} }];

